"""`uv run minimeater-sim`: runs the ngspice checks and writes docs/sim/probe-frontend.md."""

from pathlib import Path

import numpy as np

from ..model.probes import PROBES
from . import budget as Q, buck_ti as BT, dissipation as DI, fan as FN, frontend as F, ngspice, power as W, rails as RL

TEMPS_F = (32, 150, 225, 325, 500)
TOPOLOGIES = ("as_drawn", "bias_at_tip")


def power_report(out: Path) -> None:
    md = ["# 5 V input in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/power.py`). USB source 5.25 V behind the cable's L and R, "
          "D1 SMF5V0A (6.8 V breakdown, 0.11 ohm) and C38/C41 100 nF on VBUS_RAW, then U12 TPS259531 eFuse (behavioural: 34 mohm, "
          f"{W.EFUSE_ILIM:.2f} A limit from R35 1k, {W.EFUSE_SR / 1e3:.1f} V/ms soft start from C42 10 nF, 5.7 V output clamp, "
          f"{W.EFUSE_DELAY * 1e3:.1f} ms turn-on delay [est]) into VBUS_F: C1 100 uF, C2 and C4 10 uF, 3 x 100 nF with 3 mohm ESR. "
          "`derated` is the MLCC DC-bias loss at 5 V [est]: 45 / 55 / 55 / 90 %. "
          "Absolute maximum at VBUS_F: 6 V on the TLV62569 (SLVSDG1C) and the TLV75533P (VIN), 7 V on the TPS2553 (IN, OUT); "
          "20 V at the eFuse's input (SLVSE57C). The first board's PTC (F1) is the `ptc` column, for comparison.", "",
          "## Hot plug", "",
          "| Caps | Cable L | Cable R | Peak at VBUS_F | (PTC) | Peak at the eFuse input | Source current peak | (PTC) | Charge in the first 100 us | (PTC) |",
          "|---|---|---|---|---|---|---|---|---|---|"]
    for caps in ("nominal", "derated"):
        for l in (0.25e-6, 1e-6, 2e-6):
            for r in (0.05, 0.1, 0.2):
                h = W.hotplug(W.HotPlug(l, r, caps))
                p = W.hotplug(W.HotPlug(l, r, caps, front_end="ptc"))
                md.append(f"| {caps} | {l * 1e6:g} uH | {r} ohm | {h['vbus_f_peak']:.2f} V | {p['vbus_f_peak']:.2f} V | "
                          f"{h['vbus_raw_peak']:.2f} V | {h['i_peak']:.1f} A | {p['i_peak']:.0f} A | "
                          f"{h['charge_100us'] * 1e6:.1f} uC | {p['charge_100us'] * 1e6:.0f} uC |")
    md += ["", "With the PTC, the board's 100 uF sat straight on the cable: a long, thick cable rang VBUS_F to 6.6-7.2 V, over "
           "the 6 V parts, and every plug-in drew 15-40 A and 0.3-0.6 mC in tens of microseconds, against USB's 50 uC "
           "inrush guideline (minimeat-kqt, minimeat-brt). The eFuse fixes both. At attach the cable sees only the 100 nF "
           "input caps (a couple of uC); it rings the input to about 7 V, where D1 clamps it, far under the eFuse's 20 V. "
           "VBUS_F then rises at the soft-start rate, about half an amp into the board's capacitance for a millisecond, "
           "and never above 5.3 V. More input capacitance (1-2 uF) only puts more energy into the TVS, so the input keeps "
           "the datasheet's 0.1 uF (C41, at the IN pins) and C38 at the connector.", "",
           "UVLO: R33 100k over R34 43.2k puts EN at 3.98 V rising, 3.65 V falling (1.2/1.1 V thresholds), and keeps the EN "
           "pin under its 7 V rating while the input rings. FLT is not used: when the eFuse trips, the board is off.", "",
           "## Load-switch turn-on (worst case: no slew limit)", "",
           "Switch into the output capacitance at its current limit; 5 V rail behind 0.5 ohm with 130 uF and 0.3 A of other load.", "",
           "| Output | C out | Limit | Rail minimum | Time in limit | Source peak |", "|---|---|---|---|---|---|"]
    for name, c, lim in (("servo (U6, R5 43.2k)", 110e-6, 0.6), ("servo, derated", 52e-6, 0.6), ("fan (U7, R6 49.9k)", 10.2e-6, 0.519)):
        i = W.inrush(c, lim, 0.5, 0.3)
        md.append(f"| {name} | {c * 1e6:.0f} uF | {lim:.2f} A | {i['vin_min']:.2f} V | {i['t_limit'] * 1e3:.2f} ms | {i['i_src_peak']:.2f} A |")
    md += ["", "The rail stays above 4.5 V. The source current is 0.9 A for about a millisecond, "
           "over a Default-class (500 mA) port's limit: firmware should enable the servo only on a 1.5 A or 3 A source, "
           "or while the fan and radio are quiet (ICD: loads are limited by source class).", ""]
    md += ["## 3V3 buck (TLV62569, checked against the datasheet, not simulated)", "",
           "- L1 2.2 uH with 3 x 10 uF at the output is the datasheet's standard LC (Table 4, 10 uF at 2.2 uH, also proven at 22 and 2 x 22 uF); "
           "with the DC-bias loss at 3.3 V (about 55 %) and the -50 % tolerance the effective output capacitance is still above the 10 uF row.",
           "- R3 453k / R4 100k with C7 6.8 pF: 3.32 V, and the 6.8 pF feed-forward is the datasheet's value for R2 = 100k (R2 maximum 200k).",
           "- Switching 1.5 MHz, high-side current limit 3 A, soft start 800 us, UVLO 2.3-2.45 V falling: the servo turn-on above leaves the rail at 4.5 V, far from UVLO.",
           "- There is no vendor model of the buck for ngspice: `rails.md` runs the 5 V and 3V3 transients with a behavioural one (constant-power "
           "input, the datasheet's own load-step capture at the output); measure the 3V3 ripple and a Wi-Fi burst at bring-up.", ""]
    (out / "power.md").write_text("\n".join(md))
    print(out / "power.md")


def dissipation_report(out: Path) -> None:
    sc = DI.SCENARIOS
    res = [DI.solve(s) for s in sc]
    names = ("cook", "worst normal", "1.5 A budget")
    parts = (("D1", "SMF5V0A TVS"), ("U12", "TPS259531 eFuse"), ("U4", "TLV62569 buck (with L1)"),
             ("U5", "TLV75533P LDO"), ("U6", "TPS2553, servo"), ("U7", "TPS2553, fan"))
    md = ["# Power tree dissipation", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/dissipation.py`). Closed form: what each part on the 5 V path "
          "burns at ADR 0004's operating points, and the junction temperature that gives with the board at its 85 C ceiling "
          "(ICD). Datasheet figures are `[spec]`; `[fig]` is read off a datasheet graph (about 1 point); `[est]` is ours. "
          "The first board's PTC (F1) is gone: U12 replaced it (minimeat-8s2). Topology, from the board: J1 - D1 - U12 - VBUS_F; "
          "VBUS_F feeds U4 (3V3: MCU, ADS122C04 DVDD, TMP117, ATECC608B), U5 through FB1 (3V3A: ADS122C04 AVDD and the probe "
          "bias) and the two load switches U6 (servo) and U7 (fan).", "",
          "## Operating points", "",
          "| | " + " | ".join(names) + " |", "|---|" + "---|" * len(names),
          "| 3V3 rail load (ADR 0004) | " + " | ".join(f"{s.i_3v3 * 1e3:.0f} mA" for s in sc) + " |",
          "| U5 load (ADS122C04 AVDD + ref, four probe biases) | " + " | ".join(f"{DI.I_ANALOG * 1e3:.2f} mA" for _ in sc) + " |",
          "| Fan, 5 V | " + " | ".join(f"{s.i_fan * 1e3:.0f} mA" for s in sc) + " |",
          "| Servo, 5 V | " + " | ".join(f"{s.i_servo * 1e3:.0f} mA" for s in sc) + " |",
          "| U4 efficiency (curve less 2 points) | " + " | ".join(f"{r['eta']:.1%}" for r in res) + " |",
          "| Input current at VBUS_RAW | " + " | ".join(f"{r['i_in'] * 1e3:.0f} mA" for r in res) + " |",
          "| Power from the USB source (5.0 V) | " + " | ".join(f"{r['p_in']:.2f} W" for r in res) + " |", "",
          "U4's efficiency is Figure 9 of SLVSDG1C (3.3 V out, 5 V in) `[fig]`: 94 % at 10 mA, 95 % from 100 mA to 1 A, 92 % at 2 A. "
          "Two points come off for what the curve does not carry: its inductor, its layout and 25 C against our L1 (78 mohm max "
          "`[est]`, distributor listings) and 85 C. The datasheet gives no switching or gate-drive loss, so the curve is the only "
          "source for that part of U4's loss. The 1.5 A budget case draws about 1.04 A at the input, inside the "
          "1.5 A the source must advertise (ADR 0004, amendment).", "",
          "## Power in each part", "",
          "| Part | " + " | ".join(f"{n} (mW)" for n in names) + " | Basis |", "|---|" + "---|" * (len(names) + 1)]
    basis = {"D1": "leakage 0.4 mA max at 5 V `[est]`", "U12": "I^2 x 47 mohm (85 C max) + 250 uA IQ `[spec]`",
             "U4": "efficiency curve `[fig]`; conduction share below", "U5": "(5 V - 3.32 V) x load + 33 uA ground current `[spec]`",
             "U6": "I^2 x 135 mohm (max over temperature) + 140 uA `[spec]`", "U7": "same"}
    for k, name in parts:
        md.append(f"| {k} {name} | " + " | ".join(f"{r[k] * 1e3:.1f}" for r in res) + f" | {basis[k]} |")
    md.append("| **Board total** | " + " | ".join(f"**{r['p_board'] * 1e3:.0f}**" for r in res) + " | |")
    md.append("| as a share of the USB power | " + " | ".join(f"{r['p_board'] / r['p_in']:.1%}" for r in res) + " | |")
    md += ["", "U4's loss splits into the part the datasheet's resistances give (both FETs over a cycle at 105 C, L1's DCR, 35 uA "
           "IQ) and the rest: " + ", ".join(f"{n} {r['buck_conduction'] * 1e3:.0f} of {r['U4'] * 1e3:.0f} mW" for n, r in zip(names, res))
           + ". The rest is switching and gate drive, taken from the curve.", "",
           "A linear regulator in U4's place would burn (5 V - 3.32 V) x 0.352 A = "
           f"{(DI.V_BUS - DI.V_3V3) * sc[1].i_3v3:.2f} W at the TX burst (ADR 0004's 0.6 W), "
           f"a {(DI.V_BUS - DI.V_3V3) * sc[1].i_3v3 * DI.THETA['U5']:.0f} C rise in a SOT-23: the buck stays.", "",
           "## Junction temperatures", "",
           f"Board at {DI.T_BOARD:.0f} C, junction-to-ambient from the datasheets (JEDEC, so high: the board's planes do better), "
           f"each part at its worst row above. Limit {DI.TJ_MAX:.0f} C for U4, U5, U6, U7 and U12; D1 is held to the same "
           "figure for simplicity (a TVS is rated higher).", "",
           "| Part | Worst power | Theta JA | Rise | Tj | Margin to 125 C |", "|---|---|---|---|---|---|"]
    for k, name in parts:
        p = max(r[k] for r in res)
        t = DI.tj(k, p)
        md.append(f"| {k} {name} | {p * 1e3:.1f} mW | {DI.THETA[k]:.0f} C/W | {p * DI.THETA[k]:.1f} C | {t:.0f} C | {DI.TJ_MAX - t:.0f} C |")
    md += ["", "U4 is the hot part, with 23 C of margin on a theta that is the datasheet's worst; everything else stays within "
           "10 C of the board. The whole board puts out under 0.2 W, which warms a 46 x 54 mm board by a few kelvin at most "
           "`[est]`: the case's thermal problem is the duct and the servo (ADR 0004), not self-heating.", "",
           "## Fault cases", "",
           "| Case | Current | Drop across the part | Power | Steady-state Tj (never reached) | Ends by |", "|---|---|---|---|---|---|"]
    ends = {"U6": "U6's thermal shutdown (135 C in current limit, `[spec]`) cycles it; FAULT asserts after 5-10 ms and the firmware latches `load` after three one-second samples",
            "U7": "same, U7",
            "U12": "157 C shutdown in a few ms at 85 C (Figure 26 `[fig]`), then auto-retry every 93 ms (the auto-retry variant `[spec]`); the source's own limit also applies"}
    seen = set()
    for case, f in DI.faults().items():
        key = case.split(",")[0].split(" ")[0]
        end = ends[key] if key not in seen else "as above"
        seen.add(key)
        md.append(f"| {case} | {f['i']:.2f} A | {f['drop']:.1f} V | {f['p']:.1f} W | {DI.tj(key, f['p']):.0f} C | {end} |")
    md += ["", "In current limit a TPS2553 is a constant-current source (no foldback), so a stalled servo (4-5 ohm across a 0.6 A limit) "
           "leaves 1.1-1.5 W in a SOT-23 whose theta would take it to 300 C: the thermal shutdown ends it, by design (ADR 0004). "
           "What the datasheet does not give is how many seconds that takes to reach 135 C on this board, nor how warm the board "
           "gets in the three seconds before the firmware latches the fault; that goes into the bring-up list (`.3.9`).", ""]
    e = DI.efuse_start()
    md += ["## Switch-on and surge", "",
           f"- **U12 soft start:** it carries C dV/dt = {e['i'] * 1e3:.0f} mA into {e['c'] * 1e6:.0f} uF of VBUS_F "
           f"at 4.2 V/ms for {e['t'] * 1e3:.1f} ms while its drop falls from 5 V to nothing: {e['energy'] * 1e3:.1f} mJ, {e['p_avg']:.1f} W "
           "average for that millisecond, then 0.05 W. The datasheet's thermal-shutdown time at 85 C is over a second at 1.3 W "
           "(Figure 26 `[fig]`), against a pulse of 1.2 ms.",
           "- **D1 in a hot plug** (the 18 corners of `power.md`, 0.25-2 uH and 0.05-0.2 ohm of cable, nominal and derated caps): "
           + _tvs_surge() + " against the SMF5.0A's 200 W / 21.7 A pulse rating `[est]`, so D1 sees nothing like its rating at plug-in.", "",
           "## Other limits met",
           "",
           f"- **L1:** peak current at the TX burst is {sc[1].i_3v3:.2f} A + half the ripple, "
           f"{DI.V_3V3 * (1 - DI.V_3V3 / DI.V_BUS) / (2.2e-6 * 1.5e6) / 2:.2f} A at nominal L, so {sc[1].i_3v3 + DI.V_3V3 * (1 - DI.V_3V3 / DI.V_BUS) / (2.2e-6 * 1.5e6) / 2:.2f} A "
           f"against Isat {DI.L1_ISAT:.1f} A `[est]`. U4's high-side limit ({DI.BUCK_ILIM:.0f} A) is above that Isat, so a hard short on 3V3 "
           "drives L1 into saturation until the limit or U12 (2.04 A in) steps in; nothing the board does in normal running comes near it.",
           f"- **Power banks:** the cook case draws {res[0]['i_in'] * 1e3:.0f} mA at VBUS_RAW, 0.45 W. ADR 0004 put it at about 120 mA and worried "
           "about banks that cut off under 50-100 mA; that is at the top of the band where banks may cut off, so the question stands. "
           "The keep-alive footprint ADR 0004 allows for stays open for bring-up (`.3.9`), when a real bank can be tried.", ""]
    (out / "dissipation.md").write_text("\n".join(md))
    print(out / "dissipation.md")


def _tvs_surge() -> str:
    pk = en = 0.0
    for caps in ("nominal", "derated"):
        for l in (0.25e-6, 1e-6, 2e-6):
            for r in (0.05, 0.1, 0.2):
                h = W.hotplug(W.HotPlug(l, r, caps))
                pk, en = max(pk, h["tvs_peak"]), max(en, h["tvs_energy"])
    return f"at most {pk:.1f} A and {en * 1e6:.0f} uJ"


def rails_report(out: Path) -> None:
    g = RL.scenarios()
    ti = RL.ti_crosscheck(g)
    bk = BT.checks() if ti is not None else None
    d_dyn = RL.DIP_V_PER_A * (RL.Rails().i_mcu_tx - RL.Rails().i_mcu_idle)
    ripple = 0.1 * 7.5e-6 / RL.C_OUT_3V3  # Figure 15's 0.1 V pk-pk on about 7.5 uF, same charge per pulse (conservative at 3.3 V)
    floor = RL.V3_LOW - d_dyn - ripple
    md = ["# 5 V and 3.3 V rail transients in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/rails.py`). The whole power path of the schematic: USB source (V, "
          "cable R and L, or a current-limited port) - D1 and C38/C41 - U12 eFuse (as in `power.md`, with its 3.65 V falling UVLO) - "
          "VBUS_F (C1, C2, C4, 100 nF, derated) - U4 (3V3), U5 behind FB1 (3V3A), the U6 servo and U7 fan switches into their "
          "output capacitors and loads. The module's draw is 80 mA idle and 352 mA in a TX burst (ADR 0004), edges 1 us.", "",
          "U4 is two behavioural halves (TI's own transient model also runs, and is compared below). Its **input** is a constant-power load "
          f"(93 % efficient, UVLO {RL.BUCK_UVLO_ON} V on / {RL.BUCK_UVLO_OFF} V off, 0.8 ms soft start): that is what the 5 V rail sees. "
          f"Its **output** is the regulated 3V3 less the load step's droop from the datasheet's own transient capture (SLVSDG1C "
          f"Figure 18: a 1.2 A step at 1 A/us dips 0.2 V and recovers in about 4 us, so {RL.DIP_V_PER_A:.3f} V per amp and 4 us, as a "
          "high-pass on the load current), less dropout when VBUS_F is too low to regulate. A PI loop tuned to that capture did not "
          "behave like the part (DCS-Control has far more DC gain than the capture can set), so the capture is used as measured. "
          "The 3V3 set point is the low end of its window for the minima (VFB 0.588 V, 1 % resistors: "
          f"{RL.V3_LOW:.3f} V) and the high end for the overshoots ({RL.V3_HIGH:.3f} V). The module needs 3.0 V "
          "(ESP32-C6-WROOM-1 VDD33 minimum `[spec]`); the brownout detector's threshold is set in firmware (not read here).", "",
          "## 3V3 budget", "",
          "| | |", "|---|---|",
          f"| Regulation window, low end | {RL.V3_LOW:.3f} V |",
          f"| TX burst step (80 to 352 mA) | -{d_dyn * 1e3:.0f} mV |",
          f"| PSM ripple, scaled from Figure 15 (0.1 V pk-pk on about 7.5 uF, same charge per pulse, {RL.C_OUT_3V3 * 1e6:.1f} uF here) `[est]` | -{ripple * 1e3:.0f} mV |",
          f"| **Lowest 3V3** | **{floor:.3f} V** |",
          f"| Margin to the module's 3.0 V | {1e3 * (floor - RL.V_MCU_MIN):.0f} mV |", "",
          f"U4 regulates until VBUS_F falls to 3.32 V + 0.35 A x {RL.DROPOUT_R * 1e3:.0f} mohm = {3.318 + 0.35 * RL.DROPOUT_R:.2f} V; the eFuse's UVLO "
          f"turns the board off at {RL.UVLO_EFUSE_OFF} V, so the first thing to give on a sagging 5 V is the whole board, "
          "not the 3V3 rail. 3V3A stays at 3.30 V in every case below (a 3.3 V LDO from at least 4.4 V).", ""]

    def row(name, m, cols):
        return f"| {name} | " + " | ".join(c(m) for c in cols) + " |"

    t_up = lambda m: f"{m['t_3v3'] * 1e3:.2f} ms"
    md += ["## Plug-in and power-on", "",
           "| Source | 3V3 reaches 3.0 V | 3V3 peak | VBUS_F peak | VBUS_RAW peak | Source current peak |", "|---|---|---|---|---|---|"]
    for n, r, m in g["plug"]:
        md.append(row(n, m, (t_up, lambda m: f"{m['v3_max']:.2f} V", lambda m: f"{m['vbus_f_max']:.2f} V",
                             lambda m: f"{m['vbus_raw_max']:.2f} V", lambda m: f"{m['i_src_max']:.2f} A")))
    md += ["", "VBUS_F follows the eFuse's 4.2 V/ms ramp after its 0.4 ms delay, the buck starts at 2.45 V and ramps 3V3 over 0.8 ms: "
           "3V3 is up 1.7 ms after the plug-in, with no overshoot beyond the set point's window. The cable rings VBUS_RAW to about 7 V "
           "as in `power.md`; VBUS_F never passes the source voltage. A 0.5 A port boots the board with the loads gated: the "
           "derated bulk takes C dV/dt = 0.26 A (0.5 A with nominal capacitors) and the module's 80 mA.", "",
           "## TX bursts", "",
           "Three 0.5 ms bursts, 1 ms apart. Set point at the low end of its window.", "",
           "| Source | 3V3 minimum | 3V3 maximum | VBUS_F minimum |", "|---|---|---|---|"]
    for n, r, m in g["tx"]:
        md.append(row(n, m, (lambda m: f"{m['v3_min']:.3f} V", lambda m: f"{m['v3_max']:.3f} V", lambda m: f"{m['vbus_f_min']:.2f} V")))
    md += ["", "The burst takes 0.25 A from VBUS_F; the 5 V side drops by the source's resistance (about 75 mV at 0.3 ohm) and the 3V3 "
           "droop is the datasheet's, 45 mV. The 3V3 rises by the same amount when the burst ends.", "",
           "## Fan, servo stall and a TX burst together", "",
           "The fan is switched on at 7 ms, the servo at 8 ms with its rotor locked (the switch holds it at its 0.6 A limit, "
           "`dissipation.md`), then three TX bursts from 9 ms. Set point low.", "",
           "| Source | 3V3 minimum | 3V3A minimum | VBUS_F minimum | VBUS_RAW minimum | Result |", "|---|---|---|---|---|---|"]
    for n, r, m in g["chain"]:
        res = (f"**brownout** {1e3 * (m['t_end'] - r.t_servo):.2f} ms after the servo switch-on: VBUS_RAW falls to the eFuse's UVLO"
               if m["brownout"] else "holds")
        md.append(row(n, m, (lambda m: f"{m['v3_min']:.3f} V", lambda m: f"{m['v3a_min']:.2f} V", lambda m: f"{m['vbus_f_min']:.2f} V",
                             lambda m: f"{m['vbus_raw_min']:.2f} V", lambda m: res)))
    md += ["", "On a 1.5 A source at its worst (4.75 V, 0.3 ohm of cable) the rail never goes under 4.6 V and 3V3 stays above 3.15 V "
           "(3.11 V with the PSM ripple of the budget above). On a 0.5 A port the servo's switch-on alone takes the 5 V down to the "
           "eFuse's UVLO in a fifth of a millisecond (the run ends there): the board would reset, and again each time the servo "
           "were enabled after the reboot. That is ADR 0004's amendment in "
           "a waveform: the supply check must keep the servo off until CC says 1.5 A, because no capacitor can bridge it (the "
           "servo's 0.6 A limit plus the fan and radio is 1.1 A against 0.5 A). A 1.0 A port holds in this test, but only because "
           "the bursts are short and the 5 V sags to 4.3 V; a real port that folds back at its limit may not. "
           "The model's source is ideal up to its limit (no regulation delay, no foldback or hiccup).", "",
           "## Bulk capacitance", "",
           "The worst chain on a 4.75 V, 0.3 ohm, 2 uH cable, with the VBUS_F bulk (C1, 100 uF 1210, 45 uF derated) swept:", "",
           "| C1 | VBUS_F minimum | 3V3 minimum |", "|---|---|---|"]
    for n, r, m in g["bulk"]:
        n = "C1 omitted" if r.c1 < 1e-8 else n
        md.append(row(n, m, (lambda m: f"{m['vbus_f_min']:.2f} V", lambda m: f"{m['v3_min']:.3f} V")))
    md += ["", "The rail's margin does not come from the bulk. Taking C1 out changes VBUS_F's minimum by 10-20 mV: the minimum is the "
           "cable's drop (0.3 ohm x 0.85 A), and C2, C4 and the 100 nF caps already carry the sub-microsecond steps. "
           "The bulk also does not ride through a source interruption: the TPS259531's feature list has no reverse-current blocking, "
           "so its output discharges back into the cable. What it costs is the plug-in current, C dV/dt at the eFuse's 4.2 V/ms "
           "(0.26-0.5 A for the 100 uF). So 22 uF would hold every scenario here; C1 stays at 100 uF because it is already on the "
           "BOM (the part C36 uses too), ADR 0004 sized it (100-220 uF) to absorb the servo's start and the WiFi bursts, which a real "
           "charger's slower regulation needs more than this model's ideal source does, and it does not endanger the 0.5 A port's boot. If bring-up shows ripple on VBUS_F at the servo's "
           "PWM or the radio, the capacitance is the first thing to look at; if it does not, there is room to drop it.", "",
           *_ti_section(ti, bk),
           "## Not covered", "",
           "- U4's loop and PSM ripple (the capture-based droop above stands in for them, TI's model is optimistic about both): "
           "measure the 3V3 ripple and a burst's dip at bring-up (`.3.9`, `.3.15` compares them with this).",
           "- USB PD voltage transitions: none, the board is 5 V only (ADR 0004).",
           "- A source with foldback or hiccup, and a cable with its own capacitance.",
           "- U5's PSRR (the probe supply's ripple is in `probe-frontend.md`).", ""]
    (out / "rails.md").write_text("\n".join(md))
    print(out / "rails.md")


def _ti_section(ti, bk) -> list[str]:
    """`rails.md`'s section on TI's transient model: against the datasheet, at the board's points, and in the loop."""
    if ti is None or bk is None:
        return ["## TI's transient model", "",
                "Not run: TI's TLV62569 model could not be fetched (`ti_models.py`; set `MINIMEATER_TLV62569_LIB` to a copy).", ""]
    f15, f18, tx, pts = bk["fig15"], bk["fig18"], bk["tx"], bk["points"]
    budget_floor = RL.V3_LOW - RL.DIP_V_PER_A * (RL.Rails().i_mcu_tx - RL.Rails().i_mcu_idle) - 0.1 * 7.5e-6 / RL.C_OUT_3V3
    v3_top = max(mt["v3_max"] for *_, mt in ti)
    md = ["## TI's transient model", "",
          "TI publishes an unencrypted PSpice model of the TLV62569 (SLVMBW3: adaptive off time, peak current, PSM). It runs in ngspice "
          "after two syntax changes (`ti_models.py`; the file is fetched on first use and is not in the repo). Here it is first "
          "checked against the datasheet's waveforms, then used as U4 in the full netlist (`Rails(buck=\"ti\")`) for six of the "
          "scenarios above.", "",
          "### Against the datasheet", "",
          "At the datasheet's own conditions (SLVSDG1C Table 3: 5 V in, 1.8 V out, 2.2 uH, 10 uF, no C3), read off its figures:", "",
          "| | Model | Datasheet |", "|---|---|---|",
          f"| PSM ripple at 0.1 A (Figure 15) | {f15['pp'] * 1e3:.0f} mV pk-pk | about 90 mV `[fig]` |",
          f"| 0.8 A to 2 A at 1 A/us, dip (Figure 18) | {f18['dip'] * 1e3:.0f} mV, lowest at {f18['t_dip'] * 1e6:.1f} us | about 200 mV `[fig]` |",
          f"| Overshoot on the release | {f18['overshoot'] * 1e3:.0f} mV | about 170-200 mV `[fig]` |",
          f"| Back within 20 mV | {f18['t_back'] * 1e6:.1f} us | about 4-5 us `[fig]` |", "",
          "At the board's 3V3 (R3/R4/C7, the derated output capacitors, 5 V in):", "",
          "| Load | Ripple pk-pk | Level (mean) | Efficiency, model | Efficiency, Figure 9 |", "|---|---|---|---|---|"]
    for p in pts:
        md.append(f"| {p['i'] * 1e3:.0f} mA | {p['pp'] * 1e3:.1f} mV | {p['mean']:.3f} V | {p['eta']:.1%} | {p['eta_fig9']:.1%} |")
    md += ["",
           f"The model's PSM ripple is {f15['pp'] / 0.09:.0%} of the datasheet's at Figure 15's conditions, its load-step dip is "
           f"{f18['dip'] / 0.2:.0%} of the figure's, and its efficiency is 2-4 points above the curve: it has no switching or "
           "gate-drive loss. So it is not a better budget than the capture-based one, and **the 3V3 floor above stays on the "
           "datasheet's numbers**. In PSM the model's output sits above its set point (idle mean "
           f"{pts[0]['mean'] - RL.V3_NOM:+.3f} V at 30 mA, as the datasheet says it does), so the low end of the window is the "
           f"idle *valley*: from it the TX burst takes the model {tx['drop'] * 1e3:.0f} mV more "
           f"(lowest {tx['min_burst']:.3f} V from a valley of {tx['valley_pre']:.3f} V, {tx['pp_pre'] * 1e3:.0f} mV of ripple at idle); "
           f"on the release it overshoots {tx['overshoot'] * 1e3:.0f} mV. Start-up with 80 mA on it takes {tx['t_up'] * 1e6:.0f} us "
           f"to 90 % (the behavioural model's 0.8 ms soft-start ramp, `[spec]`, is slower), peaking at {tx['start_max']:.3f} V "
           f"({1e3 * (tx['start_max'] - RL.V3_NOM):.0f} mV over its set point). On the model's drop the floor would be "
           f"{RL.V3_LOW - tx['drop']:.2f} V, not the budget's {budget_floor:.3f} V.", "",
           "### In the loop", "",
           "The same netlists as above with the model as U4 (EN on VIN, the 3V3 load a current sink, and the efficiency it lacks "
           "drawn from VBUS_F as an extra load). `beh` is the behavioural U4 of the sections above.", "",
           "| Scenario | 3V3 up, beh / TI | 3V3 minimum, beh / TI | 3V3 maximum, beh / TI | VBUS_F minimum, beh / TI | Result, beh / TI |",
           "|---|---|---|---|---|---|"]
    for n, r, m, mt in ti:
        def res(x, r=r):
            return f"brownout at +{1e3 * (x['t_end'] - r.t_servo):.2f} ms" if x["brownout"] else "holds"
        md.append(f"| {n} | {m['t_3v3'] * 1e3:.2f} / {mt['t_3v3'] * 1e3:.2f} ms | {m['v3_min']:.3f} / {mt['v3_min']:.3f} V | "
                  f"{m['v3_max']:.3f} / {mt['v3_max']:.3f} V | {m['vbus_f_min']:.2f} / {mt['vbus_f_min']:.2f} V | {res(m)} / {res(mt)} |")
    md += ["",
           "The 5 V side agrees: the VBUS_F minima agree to within 10 mV, and a 0.5 A port browns out at the same "
           "point, on the servo's switch-on, in both. That is what the constant-power load was for, and TI's switching model, "
           "chopping the input current at 1.4 MHz into the 100 uF and the eFuse, does not change it. The 3V3 minima in the "
           "model are higher than the behavioural ones for the reasons above (its PSM rise, shallower dip): they are not a "
           "second opinion on the floor. The maxima are new: with the set point at the high end of its window "
           f"({RL.V3_HIGH:.3f} V) the model's PSM puts 3V3 up to {v3_top:.2f} V at plug-in, {(v3_top - RL.V3_HIGH) * 1e3:.0f} mV over "
           "the window, still inside the module's 3.6 V maximum (ESP32-C6-WROOM-1 VDD33 `[spec]`).", ""]
    return md


def budget_report(out: Path) -> None:
    b = Q.B
    md = ["# Probe channel error budget", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/budget.py`). One channel as on the schematic (47k bias at "
          "the tip, 1k to the ADC pin, 100 nF), every board-side error source at its datasheet limit, the board at "
          f"{Q.T_BOARD:.0f} C. The DC solution is closed form, checked against ngspice to 1e-8 in the ratio. The probe's own "
          "tolerance, lead resistance and a damp probe's leakage are not the board's and are left out "
          "(ADR 0002, `docs/modeling/probes.md`).", "",
          "## Sources and limits", "",
          "| Source | Limit | From |", "|---|---|---|",
          f"| Bias R23 tolerance | +-{b.bias_tol:.2%} | TNPW0603 0.1 % |",
          f"| Bias R23 drift | +-{b.bias_tc:.2%} | 25 ppm/K, 25 to {Q.T_BOARD:.0f} C |",
          f"| ESD leakage at the tip | 0 to {b.esd_leak * 1e9:.0f} nA, to GND | TPD4E05U06 max over temperature (typ 10 pA, ~0.25 nA at 125 C in its Fig 5-5) |",
          f"| ADC absolute input current | +-{b.adc_in * 1e9:.1f} nA | ADS122C04, PGA bypassed: +-5 nA typ, 10 pA/C (no max is published) |",
          f"| R19 tolerance | +-{b.series_tol:.0%} | only with the input current |",
          f"| ADC gain error | +-{b.gain:.3%} | 0.05 % max (gain 1-32) + 2 ppm/C max |",
          f"| ADC offset, after subtraction | +-{b.offset * 1e6:.0f} uV | the firmware subtracts the shorted-input reading every pass [est] |",
          f"| ADC INL | +-{b.inl * 1e6:.0f} uV | 15 ppm of the +-VREF range, max |",
          f"| Noise | +-{b.noise * 1e6:.1f} uV | 3 sigma, interquartile mean of 8 conversions |",
          "| Self-heating | reads high | the probe's dissipation over 1.5 mW/K (still air; far less in meat) |", "",
          "REFP is the same node as the bias resistors' top, so the rail's value, FB2/R18 and the reference input current "
          "(+-10 nA) cancel.", "",
          "## Error against temperature (F)", "",
          "`worst` is every corner of the ranges above plus self-heating; `MC 99.7 %` is the 99.7th percentile of 4000 "
          "Monte Carlo draws (resistors, gain, offset and input current normal with the limit at 3 sigma; ESD leakage and "
          "INL uniform).", "",
          "| Probe | | " + " | ".join(f"{t} F" for t in Q.GRID_F) + " |", "|---|---|" + "---|" * len(Q.GRID_F)]
    for p in PROBES:
        md.append(f"| {p.name} | worst | " + " | ".join(f"{Q.worst_f(p, t):.2f}" for t in Q.GRID_F) + " |")
        md.append(f"| | MC 99.7 % | " + " | ".join(f"{np.percentile(np.abs(Q.monte_carlo_f(p, t)), 99.7):.2f}" for t in Q.GRID_F) + " |")
    acc = Q.accept()
    md += ["", "## Acceptance", "",
           f"- Pit, {Q.PIT_F[0]:.0f}-{Q.PIT_F[1]:.0f} F, every family: worst {acc['pit']:.2f} F (limit 1 F).",
           f"- Food, {Q.FOOD_F[0]:.0f}-{Q.FOOD_F[1]:.0f} F, every family: worst {acc['food']:.2f} F (limit 0.5 F).", "",
           "## Each source alone (F, at its worse end)", "",
           "| Probe | T | " + " | ".join(Q.TERMS + ["self_heating"]) + " |", "|---|---|" + "---|" * (len(Q.TERMS) + 1)]
    for p in PROBES:
        for t in (32, 165, 225, 500):
            tt = Q.terms_f(p, t)
            md.append(f"| {p.name} | {t} F | " + " | ".join(f"{tt[n]:.3f}" for n in Q.TERMS + ["self_heating"]) + " |")
    k = [(cs, Q.kickback(PROBES[2], 225, cs)) for cs in (5e-9 / (Q.F_MOD * Q.VCC), 5e-8 / (Q.F_MOD * Q.VCC))]
    md += ["", "## Sampling kickback (transient)", "",
           "The ADC's input as a switched capacitor at the 256 kHz modulator rate, emptied to AVSS every cycle (the worst "
           "case), on the generic 100k probe at 225 F; the reading is the mean of v(ain) over a 50 ms conversion. "
           "The datasheet gives no sampling capacitance; the first row is the capacitance whose average current is the "
           "spec's 5 nA at full scale, the second ten times that.", "",
           "| C sample | Average current | Per-cycle dip | Reading error | DC current of the same average |", "|---|---|---|---|---|"]
    for cs, r in k:
        md.append(f"| {cs * 1e15:.1f} fF | {r['i_avg'] * 1e9:.2f} nA | {r['dip_v'] * 1e9:.1f} nV | {r['err_f']:+.4f} F | {r['dc_equiv_f']:+.4f} F |")
    md += ["", "The 100 nF node takes each kick without a visible step (the per-cycle charge is fC against 100 nF), and "
           "the reading moves exactly as a DC current of the same average would: the kickback is the datasheet's input "
           "current, already in the budget. Each jack has its own 100 nF, so the mux switching between jacks needs no "
           "settling either; plug-in settling is in `probe-frontend.md`.", "",
           "## Reading it", "",
           "- In the pit and food ranges the bias resistor dominates (tolerance and drift), then the ADC's gain error. "
           "None of it is worth a part change: a 0.05 % or 10 ppm/K resistor would take a tenth of a degree off a budget "
           "that already passes with margin.",
           "- Above 400 F the 100k probes are a few hundred ohms and the ratio is small, so the ADC's INL takes over: up "
           "to about 3 F at 600 F worst case. That is outside the control range (ADR 0002).",
           "- The 1M Maverick at 32 F is 2 F worst case, mostly gain error at a ratio near 1; it is a food-probe ice-bath "
           "check, where the power-up ambient self-check and the per-probe offset trim (ADR 0002) apply.",
           "- The input-current terms (ESD and ADC) together are under 0.05 F in the bands; ADR 0002's 30 nA budget was "
           "conservative. The TPD4E05U06's 10 nA is its max over temperature, so the 'verify at 60 C' item is closed.", ""]
    (out / "probe-budget.md").write_text("\n".join(md))
    print(out / "probe-budget.md")


def fan_report(out: Path) -> None:
    md = ["# Fan PWM and tach in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/fan.py`). The board drives a 5 V 4-wire PWM fan (Noctua "
          "NF-A6x25 5V PWM, placeholder) behind the U7 load switch: GPIO, R28 100R, J6.4 for PWM; J6.3, R27 1k, R16 10k to "
          "3V3 and the pin's 45k pull-up for the tach. The fan's 20 cm lead is lumped: 0.15 uH and 15 pF per conductor "
          "and 8 pF between PWM and tach [est]. The GPIO is 17 ohm (from its IOH/IOL), its pad has clamp diodes, its "
          f"thresholds are VIH {FN.VIH:.2f} V and VIL {FN.VIL:.2f} V; the firmware's PCNT glitch filter drops pulses under "
          f"{FN.PCNT_FILTER_S * 1e6:.1f} us.", "",
          "The bead asked for a low-side MOSFET on a 12 V blower; ADR 0004 replaced that with this fan, which switches its "
          "own motor, so there is no PWM MOSFET and no 12 V tach divider. What is left to check is below.", "",
          "## Tach", "",
          "| Case | Low at the pin | High at the pin (min) | Peak at the pin | Clamp current peak | Rise 10-90 % | Longest glitch past a threshold |",
          "|---|---|---|---|---|---|---|"]
    for name, f in (("as drawn (C39 1 nF), no pull-up in the fan", FN.Fan()),
                    ("fan with a 10k tach pull-up to 5 V", FN.Fan(tach_pullup=10e3)),
                    ("PWM and tach coupled 30 pF (long lead)", FN.Fan(c_mutual=30e-12)),
                    ("without C39", FN.Fan(c_pin=0.0)),
                    ("without C39, coupled 30 pF", FN.Fan(c_pin=0.0, c_mutual=30e-12))):
        r = FN.tach_report(f)
        md.append(f"| {name} | {r['v_low']:.2f} V | {r['v_high']:.2f} V | {r['v_high_max']:.2f} V | {r['i_clamp_max'] * 1e3:.2f} mA | "
                  f"{r['rise'] * 1e6:.2f} us | {r['glitch_width'] * 1e6:.2f} us |")
    md += ["", "The levels include the PWM's crosstalk: each 25 kHz edge kicks the tach line through the lead. Without C39 "
           "the kicks take the high level down to VIH with 8 pF of coupling and through it with 30 pF, for under a "
           "microsecond (the PCNT filter, 12.8 us, would drop them), and up past 3.3 V into the pad's clamp. C39 (1 nF, "
           "the board's C19/C20 part) at the pin absorbs them: the high level stays above 3 V and nothing reaches the "
           "clamp, and the low level drops to 0.4 V. Its cost is the tach's rising edge, about 17 us through R16 and the "
           "pin's pull-up, against a tach of at most 100 Hz (3000 rpm, two pulses a revolution). It costs nothing at "
           "JLC beyond the part, so it is fitted; the PCNT filter stays as a second line.", "",
           "If the fan has its own tach pull-up to 5 V (Noctua does not publish it), the pin sits at about 4 V through the "
           "pad's clamp (3.9 V with C39), a fraction of a milliamp. That is outside the pin's 3.6 V "
           "rating: measure J6.3 with the fan powered and nothing connected at bring-up. If the fan does pull up, the "
           "fix is a divider at the pin sized from the measured value: R31 (0402, FAN_TACH to GND, not fitted) is its "
           "footprint, against R27 1k and R16 10k (raising R27 alone would lift the low level past VIL).", "",
           "## PWM at the fan's input", "",
           "The fan pulls its PWM input up inside (Intel's spec: to at most 5.25 V, sinking at most 5 mA from the "
           "controller, so not below about 1k); the value is not published, so it is swept.", "",
           "| Fan's pull-up to 5 V | Low at the fan (limit 0.8 V) | High at the fan | Overshoot | Current back into the GPIO when high |",
           "|---|---|---|---|---|"]
    for rp in (1e3, 4.7e3, 10e3, 47e3):
        r = FN.pwm_report(FN.Fan(pwm_pullup=rp))
        md.append(f"| {rp / 1e3:g}k | {r['v_low']:.2f} V | {r['v_high']:.2f} V | {r['overshoot']:.2f} V | {r['i_into_gpio'] * 1e3:.2f} mA |")
    ls = FN.load_switch()
    md += ["", "The push-pull GPIO with R28 meets the fan's 0.8 V low even at the strongest pull-up the spec allows. When "
           "the GPIO drives high the fan's pull-up pushes up to 1.5 mA back into it, which the driven pad sinks at 3.3 V. "
           "With the fan off (VFAN down) a high PWM pin would feed the fan through its input; the firmware writes 0 % duty "
           "whenever the fan is off (`tasks.rs`), so the pin is low then.", "",
           "## Load switch U7 (TPS2553, SOT-23)", "",
           f"- Running: the fan's {FN.I_FAN * 1e3:.0f} mA is DC whatever the duty (the fan switches its own motor), so 100 % "
           f"is the worst case: {ls['p_run'] * 1e3:.1f} mW at the 135 mohm maximum, {ls['rise_run']:.1f} C over the board, "
           f"{ls['drop_run'] * 1e3:.0f} mV of drop.",
           f"- Shorted or jammed fan: the switch holds its {FN.I_LIMIT:.2f} A limit with up to {ls['p_short']:.1f} W in it, "
           "and its thermal shutdown (155 C) cycles it; it pulls the shared fault line low, the firmware latches it "
           "(`drive.rs`) and the tach watch raises `fan_stall`.", ""]
    (out / "fan.md").write_text("\n".join(md))
    print(out / "fan.md")


def main() -> None:
    if not ngspice.available():
        raise SystemExit("ngspice not found (brew install ngspice)")
    out = Path("docs/sim")
    out.mkdir(parents=True, exist_ok=True)
    md = ["# Probe front-end in ngspice", "",
          "Generated by `uv run minimeater-sim` (`src/minimeater/sim/frontend.py`). One channel as on the schematic: "
          "jack tip, R19 1k, the ADC node (C29 100 nF, 30 nA leakage), 47k bias to VREF_PROBE (3V3A through FB2, R18, C27, C28). "
          "The firmware converts the ratio assuming a bare 47k bias, as in `minimeater.model.probes`.", "",
          "## Reading error, settled (degF, reading minus truth, 30 nA input current)", "",
          "`as_drawn` is the schematic before the fix (bias on the ADC side of the 1k, so the 1k adds to the probe); "
          "`bias_at_tip` is ADR 0002's order and the schematic now.", "",
          "| Probe | Topology | " + " | ".join(f"{t} F" for t in TEMPS_F) + " |", "|---|---|" + "---|" * len(TEMPS_F)]
    for p in PROBES:
        for top in TOPOLOGIES:
            row = [f"{F.dc_error_f(top, p, t):+.2f}" for t in TEMPS_F]
            md.append(f"| {p.name} | {top} | " + " | ".join(row) + " |")
    md += ["", "## Settling after a probe is plugged in (bias_at_tip)", "",
           "Time for the reading to stay within 0.01 F of its final value, node starting at VREF (empty jack). "
           "The RC is the 47k bias against 100 nF.", "", "| Probe | 32 F | 225 F | 500 F |", "|---|---|---|---|"]
    for p in PROBES:
        row = [f"{F.settle_f('bias_at_tip', p, t)[0] * 1e3:.0f} ms" for t in (32, 225, 500)]
        md.append(f"| {p.name} | " + " | ".join(row) + " |")
    md += ["", "One 20 SPS conversion is 50 ms, so the first reading after a plug-in can still be settling. Firmware should "
           "drop the first conversion after a probe appears (to check against `drivers::ads122c04`).", "",
           "## Ripple on 3V3A", "",
           "Gain from 3V3A to REFP (the filtered VREF_PROBE) and to the ADC pin, 100 k probe (about 25 C), "
           "FB2 modelled as 0.2 ohm + 0.8 uH || 700 ohm [est].", "", "| Frequency | to REFP | to ADC pin |", "|---|---|---|"]
    f = np.array([60, 1e3, 1e4, 1e5, 256e3, 1.5e6])
    _, g = F.rail_ripple_db("bias_at_tip", f, 100e3)
    for fi, (a, b) in zip(f, g):
        md.append(f"| {fi:,.0f} Hz | {a:.1f} dB | {b:.1f} dB |")
    md += ["", f"A 20 mVpp 1.5 MHz buck ripple (assumed) is {20e3 * 10 ** (g[-1, 0] / 20):.0f} uV at REFP. "
           f"The ADS122C04's average input current of 5 nA (datasheet) at its 256 kHz modulator rate is a charge of "
           f"{5e-9 / 256e3 * 1e15:.0f} fC per cycle, {5e-9 / 256e3 / 100e-9 * 1e6:.1f} uV on the 100 nF node.", ""]
    (out / "probe-frontend.md").write_text("\n".join(md))
    print(out / "probe-frontend.md")
    power_report(out)
    budget_report(out)
    fan_report(out)
    dissipation_report(out)
    rails_report(out)


if __name__ == "__main__":
    main()
